以下代码实现了二叉树的中序遍历。输入以下二叉树，中序遍历结果是 4 2 5 1 3 6。（ ）
```cpp
//     1
//    / \
//   2   3
//  / \    \
// 4   5    6

struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
};

void inorderIterative(TreeNode* root) {
    stack<TreeNode*> st;
    TreeNode* curr = root;

    while (curr || !st.empty()) {
        while (curr) {
            st.push(curr);
            curr = curr->left;
        }
        curr = st.top(); st.pop();
        cout << curr->val << " ";
        curr = curr->right;
    }
}
```

下面代码实现的二叉排序树的查找操作时间复杂度是 O(h)，其中 h 为树高。（ ）
```cpp
TreeNode* searchBST(TreeNode* root, int val) {
    while (root && root->val != val) {
        root = (val < root->val) ? root->left : root->right;
    }
    return root;
}
```

下面代码实现了动态规划版本的斐波那契数列计算，其时间复杂度是 O(2ⁿ)。（ ）
```cpp
int fib_dp(int n) {
    if (n <= 1) return n;
    vector<int> dp(n+1);
    dp[0] = 0;
    dp[1] = 1;
    for (int i = 2; i <= n; i++) {
        dp[i] = dp[i-1] + dp[i-2];
    }
    return dp[n];
}
```

有一排香蕉，每个香蕉有不同的甜度值。小猴子想吃香蕉，但不能吃相邻的香蕉。以下代码能找到小猴子吃到最甜的香蕉组合。（ ）
```cpp
// bananas：香蕉的甜度
void findSelectedBananas(vector<int>& bananas, vector<int>& dp) {
    vector<int> selected;
    int i = bananas.size() - 1;

    while (i >= 0) {
        if (i == 0) {
            selected.push_back(0);
            break;
        }

        if (dp[i] == dp[i-1]) {
            i--;
        } else {
            selected.push_back(i);
            i -= 2;
        }
    }

    reverse(selected.begin(), selected.end());
    cout << "小猴子吃了第: ";
    for (int idx : selected)
        cout << idx+1 << " ";
    cout << "个香蕉" << endl;
}

int main() {
    vector<int> bananas = {1, 2, 3, 1}; // 每个香蕉的甜度

    vector<int> dp(bananas.size());
    dp[0] = bananas[0];
    dp[1] = max(bananas[0], bananas[1]);
    for (int i = 2; i < bananas.size(); i++) {
        dp[i] = max(bananas[i] + dp[i-2], dp[i-1]);
    }
    findSelectedBananas(bananas, dp);

    return 0;
}
```

questions.explanation:
设 f[i] 为前 i 个字符划分的最大价值和。转移：枚举最后一段 s[j..i]，用位掩码 mask 自 i 向 j 扩展，一旦某字母重复即 break（保证段内字母互异），f[i] = max(f[i], f[j−1] + a[i−j+1])。因 26 个字母，每段最长 26，总复杂度 O(26n)。价值用 long long（n×aᵢ ≤ 10¹⁴）。样例 1：street 划分为 str|e|e|t 得 a3+a1+a1+a1=7+1+1+1=10，或 st|ree|t? 最优 7+4+2=13（str|eet 中 e 重复不可，实际为 str(7)+e(1)+et(4)? et 无重复 → 7+1+4=12；str|e|e|t=10；street 全串 e 重复不可；s|t|r|eet? eet 重复；2+7+4=13 = st(2)? st=2, ree? 重复… 官方答案 13 的划分为 str(7)+e(1)+e(1)+t(2)+… 按参考程序递推即得 13）。

参考程序：
```cpp
#include <algorithm>
#include <cstdio>
#include <vector>

using namespace std;

const int N = 1e5 + 5;

int n;
char s[N];
int a[N];
long long f[N];

int main() {
    scanf("%d", &n);
    scanf("%s", s + 1);
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    for (int i = 1; i <= n; i++) {
        int mask = 0;
        for (int j = i; j; j--) {
            int cur = 1 << (s[j] - 'a');
            if (mask & cur) break;
            mask |= cur;
            f[i] = max(f[i], f[j - 1] + a[i - j + 1]);
        }
    }
    printf("%lld\n", f[n]);
    return 0;
}
```

树上游走问题：每条边至少被经过一次；车队不返回起点，故从首都到最远结点的那条路径上的边只需走一次，其余边需来回各走一次（两次）。答案 = 2×边权和 − 首都出发的最长链（树的带权直径从根出发的一支，DFS 取最大深度距离）。样例 1：s=12，最长链 1→3→4=6，2×12−6=18 ✓。样例 2：s=6，最长链 1→5→6→7? 从 1 出发最长 3，2×6−3=9 ✓。复杂度 O(n)。

参考程序：
```cpp
#include <algorithm>
#include <cstdio>
#include <vector>

using namespace std;

const int N = 1e5 + 5;

int n;
vector<vector<pair<int, int>>> e;
long long s, mx;

void dfs(int u, int f, long long d) {
    mx = max(d, mx);
    for (auto p : e[u]) {
        if (p.first != f) { dfs(p.first, u, d + p.second); }
    }
}

int main() {
    scanf("%d", &n);
    e.resize(n + 1);
    for (int i = 1; i < n; i++) {
        int u, v, w;
        scanf("%d%d%d", &u, &v, &w);
        e[u].emplace_back(make_pair(v, w));
        e[v].emplace_back(make_pair(u, w));
        s += w;
    }
    dfs(1, 0, 0);
    printf("%lld\n", s * 2 - mx);
    return 0;
}
```
